/// Writes every face and every licence into `dir`, creating it if needed.
///
/// Flat, by the names the stylesheet uses, so several crates of faces
/// write into one directory. A file already holding the same bytes is
/// left alone, so a build script that calls this on every build touches
/// nothing a file watcher is watching.
///
/// # Errors
///
/// Whatever the filesystem reports: a directory that cannot be created, a
/// file that cannot be written.
pub fn write_to(dir: impl AsRef<Path>) -> std::io::Result<()> {
    let dir = dir.as_ref();
    std::fs::create_dir_all(dir)?;
    let texts = LICENCES.iter().map(|(name, text)| (*name, text.as_bytes()));
    for (name, bytes) in FILES.iter().copied().chain(texts) {
        let path = dir.join(name);
        if std::fs::read(&path).is_ok_and(|old| old == bytes) {
            continue;
        }
        std::fs::write(&path, bytes)?;
    }
    Ok(())
}
